// 1. High-Frequency Driver Location Ping (Every 4 Seconds)
PUT /api/v1/drivers/location
Request:
{
  "driver_id": "drv_49102",
  "latitude": 37.774929,
  "longitude": -122.419416,
  "bearing_degrees": 182,
  "timestamp_ms": 1790784500000
}
Response (200 OK):
{
  "h3_cell_res8": "8828308281fffff",
  "cell_changed": true
}

// 2. Rider Request Ride
POST /api/v1/rides/request
Request:
{
  "rider_id": "rdr_8821",
  "pickup": { "lat": 37.7751, "lng": -122.4193 },
  "dropoff": { "lat": 37.7899, "lng": -122.4014 },
  "tier": "UBER_X"
}
Response (201 Created):
{
  "request_id": "req_99102",
  "status": "DISPATCHING",
  "quoted_fare_cents": 1850,
  "surge_multiplier": 1.2
}

// ---------------------------------------------------------------------------
// Core Storage Entities & Schema Definitions
// ---------------------------------------------------------------------------
ENTITY driver_locations_h3 (Redis In-Memory Spatial Index) {
  [PK ] driver_id              UUID
  [IDX] h3_cell_res8           UINT64 (Hex Cell ID)
        lat_lng                GEO_POINT
        status                 ENUM('AVAILABLE','ON_TRIP')
        updated_epoch_ms       INT64 (TTL 15s)
}

ENTITY ride_requests (PostgreSQL / CockroachDB) {
  [PK ] request_id             UUID
  [IDX] rider_id               UUID
        origin_h3              UINT64
        dest_h3                UINT64
        quoted_fare_cents      INT
}

ENTITY trips (Sharded PostgreSQL + Cassandra GPS Log) {
  [PK ] trip_id                UUID
  [FK ] request_id             UUID
  [FK ] driver_id              UUID
        state                  ENUM('MATCHED','ARRIVED','IN_PROGRESS','COMPLETED')
        final_fare_cents       INT
}

// Relationships: driver_locations_h3 --(1 : N (matched to trip))--> ride_requests --(1 : 1 (fulfills ride request))--> trips
